.badge-list {
	--gap: 10px;
}

.badge-list > ul {
	display: flex;
	flex-flow: row wrap;
	justify-content: space-evenly;
	margin: 2px;
	gap: var(--gap);
}

.badge-list > ul > li {
	display: flex;
	flex-flow: column nowrap;
	align-items: stretch;
	text-align: center;
	box-sizing: border-box;
	flex: max(calc((100% / 8) - var(--gap)), 5em) 1 1;
	outline: 0px solid var(--wiki-content-link-color);
	transition: 0.1s ease-in;
}

.badge-list > ul > li:hover {
	background-color: color-mix(in srgb, var(--wiki-content-link-color) 20%, transparent);
}

.badge-list > ul > li:hover a {
	text-decoration: underline;
}

.badge-list > ul > li > a {
	display: flex;
	align-items: center;
	justify-content: center;
	height: 100%;
	flex: 1 1 auto;
	box-sizing: border-box;
	padding: 5px;
}

.badge-list > ul > li > a:first-child {
	height: 100%;
}

.badge-list > ul > li > a:last-child:not(:first-child) {
	height: unset;
}

.badge-list.stretch,
.badge-list.stretch > ul {
	height: 100%;
}

.badge-list.side-image li {
	flex-flow: row nowrap;
}

.badge-list.plain > ul > li {
	outline-color: transparent;
}

